def my1_3_day0():
    """{"shape": {z: rows}, "depth": {z: rows}} with int z keys; row y, character x."""
    raw = json.loads(zlib.decompress(base64.b64decode(_BLOB)))
    return {k: {int(z): rows for z, rows in v.items()} for k, v in raw.items()}


def answers(cx=None, cy=None, radius=None, z=145, z2=143, day=0):
    """The map in /query/map answer shape (query_result payloads): one answer for the whole map, or the square
    around (cx, cy) of the given radius, levels z..z2 (those kept)."""
    m = my1_3_day87() if day == 87 else my1_3_day0()
    if cx is None:
        x1, x2, y1, y2 = 0, 191, 0, 191
    else:
        x1, x2, y1, y2 = max(0, cx - radius), min(191, cx + radius), max(0, cy - radius), min(191, cy + radius)
    levels, liquid = [], []
    for lz in range(z, z2 - 1, -1):
        if lz not in m["shape"]:
            continue
        levels.append({"z": lz, "shape": [m["shape"][lz][y][x1:x2 + 1] for y in range(y1, y2 + 1)]})
        for y in range(y1, y2 + 1):
            row = m["depth"][lz][y]
            for x in range(x1, x2 + 1):
                if row[x] != "0":
                    liquid.append({"x": x, "y": y, "z": lz, "depth": int(row[x])})
    return {"x1": x1, "x2": x2, "y1": y1, "y2": y2, "levels": levels, "liquid": liquid}


